package com.demo.upimesh;

import com.demo.upimesh.crypto.SignatureService;
import com.demo.upimesh.model.PaymentInstruction;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;

import java.io.InputStream;
import java.util.Base64;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Proves a signature made by the browser's Web Crypto verifies in Java, and that
 * the browser's JSON field names match PaymentInstruction. The fixture is
 * generated by exportSigFixture() in the browser console.
 */
class BrowserSignatureInteropTest {

    @Test
    void signatureCreatedByWebCryptoVerifiesInJava() throws Exception {
        try (InputStream in = getClass().getResourceAsStream("/browser-signature-fixture.json")) {
            assertNotNull(in, "Missing src/test/resources/browser-signature-fixture.json. "
                    + "Generate it with exportSigFixture() in the browser console.");
            JsonNode f = new ObjectMapper().readTree(in);

            byte[] payload = Base64.getDecoder().decode(f.get("payloadBase64").asText());
            byte[] sig = Base64.getDecoder().decode(f.get("signatureBase64").asText());
            String spki = f.get("publicKeySpki").asText();

            PaymentInstruction parsed = new ObjectMapper().readValue(payload, PaymentInstruction.class);
            assertEquals("alice@demo", parsed.getSenderVpa());

            SignatureService svc = new SignatureService();
            assertEquals(64, sig.length);
            assertTrue(svc.verify(spki, payload, sig), "browser signature must verify in Java");

            payload[0] ^= 1;
            assertFalse(svc.verify(spki, payload, sig), "altered payload must fail");
        }
    }
}